    form.disabled = this.busy || !!this.plugin.settingsLoadError;
    new Setting(form)
      .setName("本文Todoを表示")
      .setDesc(
        "オフにするとカードのTodoパネルと下余白を外し、本文の読み込みも止めます。コマンド「本文Todoの表示を切り替え」は保存を待たずに即時反映します。",
      )
